Definition NODES1C : list (Z * xaction) := xconst NODES1 GD.
Lemma NODES1C_xsites : xsites NODES1C = xsites NODES1. Proof. exact (xconst_xsites NODES1 GD). Qed.
Lemma NODES1C_xksites : xksites NODES1C = xksites NODES1. Proof. exact (xconst_xksites NODES1 GD). Qed.
Lemma NODES1C_xfsites : xfsites NODES1C = xfsites NODES1. Proof. exact (xconst_xfsites NODES1 GD). Qed.
Lemma NODES1C_xhandl : xhandl NODES1C = xhandl NODES1. Proof. exact (xconst_xhandl NODES1 GD). Qed.
From Ltac2 Require Import Ltac2 Constr Std Control.
Ltac2 cert_refl_vm (rhs : constr) :=
  let g := Control.goal () in
  let r := constr:(@eq_refl _ $rhs) in
  Std.exact_no_check (Constr.Unsafe.make (Constr.Unsafe.Cast r Constr.Cast.vm g)).
Set Default Proof Mode "Ltac2".
Lemma FCF_cert : (match wstartx TM IMGW (vars_below (s_next FP0)) 10 FP0 FP0RUN NODES1C with
                  | Some l => forallb (fun X => fin_q FCF_Q FRETS (s_next FP0) (xs_st X)) l | None => false end) = true.
Proof. cert_refl_vm constr:(true). Qed.
Set Default Proof Mode "Classic".
End FcfB.

Import OSSVerify.Proofs.fast_float.from_chars.lib.M4Y.FcfBD OSSVerify.Proofs.fast_float.from_chars.lib.M4Y.FcfBThm.FcfB.
From OSSVerify.Proofs.fast_float.from_chars.lib.M4Y Require Import FxConstGen.
Import ListNotations.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope Z_scope.

Lemma TM_eq : TM = mk_tbl BSEGS 0x98cb8 1624.
Proof. vm_cast_no_check (eq_refl TM). Qed.
Lemma IMGW_eq : IMGW = mk_imgs_acc IMGR TEmpty.
Proof. vm_cast_no_check (eq_refl IMGW). Qed.
Lemma TM_ok : tbl_ok BSEGS TM.
Proof. rewrite TM_eq. apply mk_tbl_ok. Qed.
Lemma IMGW_ok : img_ok BSEGS IMGW.
Proof.
  rewrite IMGW_eq.
  apply mk_imgs_acc_ok; [unfold IMGR; repeat constructor; cbn; lia|]. intros p v Hp. rewrite tget_empty in Hp. discriminate.
Qed.
Lemma FRETS_ok : Forall (is_ret BSEGS) FRETS.
Proof. unfold FRETS. repeat constructor; exists (Z_to_bv 32 0x00008067); (split; [|split]); vm_refl_bv. Qed.
Lemma xsites_NODES1 : xsites NODES1 = [].
Proof. reflexivity. Qed.
Lemma xksites_NODES1 : xksites NODES1 = [].
Proof. reflexivity. Qed.
Lemma xfsites_NODES1 : xfsites NODES1 = [(OSSVerify.Proofs.fast_float.from_chars.lib.M4Y.FcfBD.M4B_inff.P0, OSSVerify.Proofs.fast_float.from_chars.lib.M4Y.FcfBD.M4B_inff.Q, 0x9a8c8); (SpfBD.P0, SpfBD.SPF_Q, 0x9c498)].
Proof. reflexivity. Qed.
Lemma xhandl_NODES1 : xhandl NODES1 =
  [hx_ssplitc 0x99738 29 1; hx_loopr TM IMGW (gen_rf [(9, 0, 0, 2684354559)] 400 ALLST) (EXPH 0x998d0 0x998d8); hx_ssplitc 0x99930 9 0;
   hx_rebase 0x99e90 29; hx_rebase 0x99f20 29; hx_rebase 0x9a1cc 29; hx_rebase 0x99f50 29].
Proof. reflexivity. Qed.

(* [comment removed for export] *)
Lemma kfrag_of_fn : forall P0 Q p, fn_ok BSEGS P0 Q [p] -> kfrag_ok BSEGS P0 Q p.
Proof.
  intros P0 Q p H E ms Hd. destruct (H E ms Hd) as (ms' & E' & p' & H1 & H2 & _ & H4 & H5 & H6).
  destruct H2 as [<-|[]]. exists ms', E'. exact (conj H1 (conj H4 (conj H5 H6))).
Qed.

Section Fcd.
Variable xok0 : nat -> list word -> (word -> option byte) -> Prop.
Hypothesis H_SPF : fn_ok BSEGS SpfBD.P0 SpfBD.SPF_Q [0x9c498].

#[using="H_SPF"] Theorem fcf_ok : fn_ok BSEGS FP0 FCF_Q FRETS.
Proof. LiaFast.lf_pins (fun (H_SPF : LiaFast.U) => LiaFast.u0).
  apply (fn_ok_of_wcertx BSEGS (fun _ _ _ => True) TM IMGW 10 FP0RUN NODES1C FP0 FCF_Q FRETS TM_ok IMGW_ok FCF_cert).
  - intros P0' Q' H. rewrite NODES1C_xsites, xsites_NODES1 in H. destruct H.
  - intros f H. rewrite NODES1C_xhandl, xhandl_NODES1 in H.
    destruct H as [<-|[<-|[<-|[<-|[<-|[<-|[<-|[]]]]]]]].
    + exact (hand_okxP_ok _ _ _ _ (hx_ssplitc_ok_fp BSEGS _ 0x99738 29 1)).
    + apply hx_loopr_ok; [exact TM_ok | exact IMGW_ok|].
      intros pc h Hh. destruct Hh as [Hh|[Hh|[]]]; injection Hh as _ <-; [apply hook_bare_ok | apply hook_sra63_ok; exact TM_ok].
    + exact (hand_okxP_ok _ _ _ _ (hx_ssplitc_ok_fp BSEGS _ 0x99930 9 0)).
    + apply hx_rebase_ok.
    + apply hx_rebase_ok.
    + apply hx_rebase_ok.
    + apply hx_rebase_ok.
  - intros P0' Q' H. rewrite NODES1C_xksites, xksites_NODES1 in H. destruct H.
  - intros P0' Q' pcQ H. rewrite NODES1C_xfsites, xfsites_NODES1 in H.
    destruct H as [H|[H|[]]]; injection H as <- <- <-.
    + exact (kfrag_of_fn _ _ _ OSSVerify.Proofs.fast_float.from_chars.lib.M4Y.FcfBD.M4B_inff.inff_ok).
    + exact (kfrag_of_fn _ _ _ H_SPF).
  - vm_compute. reflexivity.
  - vm_compute. reflexivity.
  - vm_compute. reflexivity.
  - exact FRETS_ok.
Qed.
End Fcd.
